136	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
137	{
138	  hybrid_state_v1 s{};
139	  s.magic = HYBRID_STATE_MAGIC;
140	  s.version = HYBRID_STATE_VERSION;
141	  s.flags = HYBRID_FLAG_RV64;
142	  s.pc = pc;
143	  s.priv = 3;
144	  s.gpr[10] = x10;
145	  return s;
146	}
147	
148	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
149	  -> std::vector<uint32_t>
150	{
151	  std::vector<uint32_t> values;
152	  for (const auto& op : ops)
153	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
154	      values.push_back(op.value);
155	  return values;
156	}
157	
158	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
159	{
160	  std::size_t n = 0;
161	  for (const auto& op : ops)
162	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
163	  return n;
164	}
