168	TEST_CASE("resume halts the hart before any abstract command")
169	{
170	  RecordingBus bus;
171	  // dmstatus answers halted+resumeack so poll loops finish on the first read.
172	  bus.dmstatus_value = (1u << 9) | (1u << 17);
173	
174	  hybrid::ResumeDriver driver(bus);
175	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));
176	
177	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
178	  // accepted; the second write must add haltreq while keeping dmactive set.
179	  REQUIRE(bus.ops.size() >= 2);
180	
181	  const auto& prime = bus.ops[0];
182	  CHECK(prime.kind == DmiOp::Kind::Write);
183	  CHECK(prime.reg == kDmcontrol);
184	  CHECK((prime.value & 1u) == 1u);                  // dmactive
185	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
186	
187	  const auto& halt = bus.ops[1];
188	  CHECK(halt.kind == DmiOp::Kind::Write);
189	  CHECK(halt.reg == kDmcontrol);
190	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
191	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
192	}
