678	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
679	          "before the architectural V-CSR restore and counter restore")
680	{
681	  RecordingBus bus;
682	  bus.dmstatus_value = (1u << 9) | (1u << 17);
683	
684	  auto s = rv64_state(0x80001000, 0);
685	  s.flags  |= HYBRID_FLAG_V;
686	  s.vlenb  = 64;
687	  s.vl     = 16;
688	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
689	  s.vstart = 7;
690	
691	  hybrid::ResumeDriver driver(bus);
692	  driver.resume(s);
693	
694	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
695	  std::vector<int> missing;
696	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
697	  for (uint16_t v = 0; v < 32; ++v) {
698	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
699	    std::optional<std::size_t> at;
700	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
701	      const auto& op = bus.ops[i];
702	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
703	          && op.value == want) { at = i; break; }
704	    }
705	    if (!at) { missing.push_back(v); continue; }
706	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
707	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
708	  }
709	  CHECK(missing.empty());
710	  REQUIRE(first_vle_idx.has_value());
711	  REQUIRE(last_vle_idx.has_value());
712	
713	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
714	  //     first and last register.
715	  auto x7_gpa_staged = [&](uint64_t gpa) {
716	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
717	      const auto& op = bus.ops[i];
718	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
719	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
720	          && ((op.value >> 16) & 1u)) {
721	        const auto& d0 = bus.ops[i - 2];
722	        const auto& d1 = bus.ops[i - 1];
723	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
724	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
725	          return true;
726	      }
727	    }
728	    return false;
729	  };
730	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa));
731	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa + 31ull * HYBRID_VLEN_BYTES_MAX));
732	
733	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
734	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
735	  //     (so the vle8.v insns cannot pollute the resumed counters).
736	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
737	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
738	    const auto& op = bus.ops[i];
739	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
740	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
741	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
742	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
743	  }
744	  REQUIRE(vstart_cmd_idx.has_value());
745	  REQUIRE(mcycle_cmd_idx.has_value());
746	  CHECK(*last_vle_idx < *vstart_cmd_idx);
747	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
748	}
