873	TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
874	{
875	  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
876	  // first polling busy. In fact write_64bit_register -> write_register_abstract
877	  // calls poll_until_clear(busy) before returning, so by the time the cmderr
878	  // check runs, busy is already clear. This test pins that contract: between
879	  // every kCommand write and the next kAbstractcs read, the recorded ops
880	  // must include at least one kAbstractcs read (the busy poll). If a future
881	  // refactor regresses by removing the chained poll, this test fails.
882	  RecordingBus bus;
