884	
885	  hybrid::ResumeDriver driver(bus);
886	  driver.resume(rv64_state(0x80001000, 0xdeadbeef));
887	
888	  // Walk ops; between each kCommand write and the very next kAbstractcs
889	  // read by an unrelated caller, there must be at least one kAbstractcs
890	  // read (the busy poll from write_register_abstract).
891	  bool saw_cmd = false;
892	  std::size_t reads_since_cmd = 0;
893	  bool all_cmds_had_abstractcs_poll = true;
894	  for (const auto& op : bus.ops) {
895	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
896	      if (saw_cmd && reads_since_cmd == 0)
897	        all_cmds_had_abstractcs_poll = false;
898	      saw_cmd = true;
899	      reads_since_cmd = 0;
900	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
901	               && op.reg == kAbstractcs) {
902	      ++reads_since_cmd;
903	    }
904	  }
905	  CHECK(all_cmds_had_abstractcs_poll);
906	  // The final kCommand write must also be followed by an abstractcs read.
907	  CHECK(reads_since_cmd > 0u);
