935	  const auto& d0 = bus.ops[idx[0] - 2];
936	  CHECK(d0.kind == DmiOp::Kind::Write);
937	  CHECK(d0.reg == kData0);
938	  CHECK((d0.value & 0x3u) == 1u);
939	
940	  // The dcsr write must land before resumereq (bit 30 of dmcontrol).
941	  std::size_t resume_idx = bus.ops.size();
942	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
943	    const auto& op = bus.ops[i];
944	    if (op.kind == DmiOp::Kind::Write && op.reg == kDmcontrol
945	        && ((op.value >> 30) & 1u) != 0u) {
946	      resume_idx = i;
947	      break;
948	    }
949	  }
950	  CHECK(idx[0] < resume_idx);
951	}
952	
953	TEST_CASE("L6: resume rejects reserved or out-of-range privilege values")
954	{
955	  RecordingBus bus;
956	  bus.dmstatus_value = (1u << 9) | (1u << 17);
957	  hybrid::ResumeDriver driver(bus);
958	
959	  auto s = rv64_state(0x80001000, 0);
960	  s.priv = 2;  // reserved encoding (H-mode slot)
961	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
962	
963	  s.priv = 4;  // out of the 2-bit prv field entirely
964	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
965	
966	  // No abstract command may have been issued for a rejected state.
967	  CHECK(count_writes_to(bus.ops, kCommand) == 0u);
968	}
969	
970	TEST_CASE("L6/L2: S/U resume mirrors the producer's PMP block, addr before cfg")
971	{
972	  // With PMP implemented and no matching entry, every S/U access faults
973	  // (priv spec v1.10) -- an S/U ROI cannot even fetch its first insn on the
974	  // vsim side unless the producer's PMP block is mirrored in.
975	  RecordingBus bus;
976	  bus.dmstatus_value = (1u << 9) | (1u << 17);
977	
978	  auto s = rv64_state(0x80001000, 0);
979	  s.priv = 0;  // U-mode
980	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb000 + i;
981	  s.pmpcfg[0] = 0x1f;  // entry 0: NAPOT, RWX
982	
983	  hybrid::ResumeDriver driver(bus);
984	  driver.resume(s);
985	
986	  std::vector<uint16_t> regnos;
987	  for (const auto& op : bus.ops)
988	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
989	        && ((op.value >> 16) & 1u) != 0u)
990	      regnos.push_back(static_cast<uint16_t>(op.value & 0xffffu));
991	
992	  // All 64 pmpaddr CSRs (0x3B0..0x3EF) and the 8 even pmpcfg CSRs
993	  // (0x3A0,0x3A2,..,0x3AE -- odd ones do not exist on RV64) are written.
994	  std::size_t first_cfg = regnos.size(), last_addr = 0;
995	  std::size_t n_addr = 0, n_cfg = 0, n_odd_cfg = 0;
996	  for (std::size_t i = 0; i < regnos.size(); ++i) {
997	    const auto r = regnos[i];
998	    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
999	    if (r >= 0x3A0 && r <= 0x3AF) {
1000	      if ((r & 1u) != 0u) ++n_odd_cfg;
1001	      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
1002	    }
1003	  }
1004	  CHECK(n_addr == 64u);
1005	  CHECK(n_cfg == 8u);
1006	  CHECK(n_odd_cfg == 0u);
1007	  // cfg activates the entries, so every addr write must precede every cfg
1008	  // write (a cfg-locked entry would discard the addr that follows it).
1009	  CHECK(last_addr < first_cfg);
1010	}
1011	
1012	TEST_CASE("L6: resume aborts loudly when the hart pins dcsr.prv (no S/U)")
1013	{
1014	  // An M-only core (e.g. NDS_NUM_PRIVILEGE_LEVELS=1 RTL) WARL-pins
1015	  // dcsr.prv to 3. Silently resuming would measure the ROI in the wrong
1016	  // privilege; the driver must verify its write took and throw instead.
1017	  RecordingBus bus;
1018	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1019	  bus.regfile[hybrid::regno_csr(kCsrDcsr)] = 0x40000003ULL;  // reset: prv=M
1020	  bus.warl_ignore.insert(hybrid::regno_csr(kCsrDcsr));
1021	
1022	  auto s = rv64_state(0x80001000, 0);
1023	  s.priv = 1;
1024	
1025	  hybrid::ResumeDriver driver(bus);
1026	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
1027	}
