  CHECK(std::memcmp(&want, &got, sizeof(want)) == 0);
}

TEST_CASE("drain_checkpoint with HYBRID_FLAG_V undoes the dump sweep's clobbers "
          "(vtype/vl via vsetvl, vstart, x5/x6/x7) before resuming")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
  bus.regfile[hybrid::regno_gpr(7)] = 0x77;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
  input.priv    = 3;
  input.vlenb   = 64;

  hybrid::StateDrain drain(bus);
  (void) drain.drain_checkpoint(input);

  // (a) the undo vsetvl runs AFTER the dump sweep's last vse8.v (v31).
  const auto last_vse =
    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
  const auto undo_vsetvl =
    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
  REQUIRE(last_vse.has_value());
  REQUIRE(undo_vsetvl.has_value());
  CHECK(*last_vse < *undo_vsetvl);

  // (b) the undo vsetvl is staged with the DRAINED vl/vtype (not the sweep's
  //     e8/m1 constants): the last x5/x6 writes before it carry 16 / 0xC1.
  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
  const auto x6_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(6));
  std::optional<uint64_t> staged_vl;
  std::optional<uint64_t> staged_vtype;
  for (const auto& [i, v] : x5_writes)
    if (i < *undo_vsetvl) staged_vl = v;
  for (const auto& [i, v] : x6_writes)
    if (i < *undo_vsetvl) staged_vtype = v;
  REQUIRE(staged_vl.has_value());
  REQUIRE(staged_vtype.has_value());
  CHECK(*staged_vl == 16u);
  CHECK(*staged_vtype == 0xC1ULL);

  // (c) vstart is restored via PB csrrw after the vsetvl (which zeroes it).
  const auto vstart_csrrw =
    last_progbuf_insn(bus.ops, hybrid::encode_csrrw(0, RD::kCsrVstart, 7));
  REQUIRE(vstart_csrrw.has_value());
  CHECK(*undo_vsetvl < *vstart_csrrw);
  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
  std::optional<uint64_t> staged_vstart;
  for (const auto& [i, v] : x7_writes)
    if (i > *undo_vsetvl && i < *vstart_csrrw) staged_vstart = v;
  REQUIRE(staged_vstart.has_value());
  CHECK(*staged_vstart == 7u);

  // (d) the scratch GPRs are restored LAST with the drained values.
  REQUIRE(!x5_writes.empty());
  REQUIRE(!x6_writes.empty());
  REQUIRE(!x7_writes.empty());
  CHECK(x5_writes.back().second == 0x55u);
  CHECK(x6_writes.back().second == 0x66u);
  CHECK(x7_writes.back().second == 0x77u);
  CHECK(x5_writes.back().first > *vstart_csrrw);

  // (e) resume comes after everything above.
  const auto resume = last_dmcontrol_write(bus.ops);
  REQUIRE(resume.has_value());
  CHECK((bus.ops[*resume].value & RD::kDmcontrolResumereq) != 0u);
  CHECK(*resume > x7_writes.back().first);
}

TEST_CASE("drain_checkpoint without HYBRID_FLAG_V issues no Program Buffer ops "
          "and still resumes")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;

  hybrid::StateDrain drain(bus);
  (void) drain.drain_checkpoint(input);

  for (const auto& op : bus.ops) {
    const bool progbuf_write =
      op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0;
    CHECK_FALSE(progbuf_write);
  }

  const auto resume = last_dmcontrol_write(bus.ops);
  REQUIRE(resume.has_value());
  CHECK((bus.ops[*resume].value & RD::kDmcontrolResumereq) != 0u);
}

// ---- drain_full (cosim_redesign F1): no QEMU1 input, everything read ----

namespace
{

// misa letter bits + RV64 MXL for composing probe values in tests.
constexpr uint64_t kMisaD    = 1ULL << 3;
constexpr uint64_t kMisaF    = 1ULL << 5;
constexpr uint64_t kMisaV    = 1ULL << 21;
constexpr uint64_t kMisaRv64 = 2ULL << 62;

}  // namespace

TEST_CASE("drain_full reads the trap CSR block from the DM (no passthrough)")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64;  // misa: no F/D/V
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)]  = 0x1888ULL;
  bus.regfile[hybrid::regno_csr(0x341)] = 0x111ULL;  // mepc
  bus.regfile[hybrid::regno_csr(0x342)] = 0x2ULL;    // mcause
  bus.regfile[hybrid::regno_csr(0x343)] = 0x333ULL;  // mtval
  bus.regfile[hybrid::regno_csr(0x340)] = 0x444ULL;  // mscratch
  bus.regfile[hybrid::regno_csr(RD::kCsrMtvec)] = 0x555ULL;
  bus.regfile[hybrid::regno_csr(0x302)] = 0x666ULL;  // medeleg
  bus.regfile[hybrid::regno_csr(0x303)] = 0x777ULL;  // mideleg
  bus.regfile[hybrid::regno_csr(0x344)] = 0x888ULL;  // mip
  bus.regfile[hybrid::regno_csr(0x304)] = 0x999ULL;  // mie
  bus.regfile[hybrid::regno_csr(0x180)] = 0xAAAULL;  // satp

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.mstatus  == 0x1888ULL);
  CHECK(state.mepc     == 0x111ULL);
  CHECK(state.mcause   == 0x2ULL);
  CHECK(state.mtval    == 0x333ULL);
  CHECK(state.mscratch == 0x444ULL);
  CHECK(state.mtvec    == 0x555ULL);
  CHECK(state.medeleg  == 0x666ULL);
  CHECK(state.mideleg  == 0x777ULL);
  CHECK(state.mip      == 0x888ULL);
  CHECK(state.mie      == 0x999ULL);
  CHECK(state.satp     == 0xAAAULL);
}

TEST_CASE("drain_full probes flags from misa and vlenb from the hart")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaF | kMisaD | kMisaV;
  bus.regfile[hybrid::regno_csr(0xC22)] = 32;  // vlenb (VLEN=256)
  // FS/VS must be on for the FPR / V reads to be accepted.
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x6600ULL;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK((state.flags & HYBRID_FLAG_RV64) != 0u);
  CHECK((state.flags & HYBRID_FLAG_FP) != 0u);
  CHECK((state.flags & HYBRID_FLAG_V) != 0u);
  CHECK(state.vlenb == 32u);
}

TEST_CASE("drain_full without F/D/V in misa: only RV64, no FPR or V-CSR reads")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.flags == HYBRID_FLAG_RV64);
  CHECK(state.vlenb == 0u);
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const uint16_t regno = op.value & 0xFFFFu;
    const bool is_fpr = regno >= hybrid::regno_fpr(0)
                     && regno <= hybrid::regno_fpr(31);
    CHECK_FALSE(is_fpr);
    CHECK(regno != hybrid::regno_csr(RD::kCsrVl));
    CHECK(regno != hybrid::regno_csr(RD::kCsrVtype));
  }
}

TEST_CASE("drain_full reads FPRs and fcsr when misa has F/D")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaF | kMisaD;
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x6600ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xf000000000000000ULL + uint64_t(i));
  CHECK(state.fcsr == 0x45u);
}

TEST_CASE("drain_full reads the PMP block via tolerant abstract reads")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64;
  for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
    bus.regfile[hybrid::regno_csr(RD::kCsrPmpaddr0 + i)] = 0xb00ULL + i;
  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
    bus.regfile[hybrid::regno_csr(RD::kCsrPmpcfg0 + i)] = 0xa00ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.pmpaddr[0]  == 0xb00ULL);
  CHECK(state.pmpaddr[63] == 0xb3fULL);
  CHECK(state.pmpcfg[0]   == 0xa00ULL);
  CHECK(state.pmpcfg[14]  == 0xa0eULL);
}

TEST_CASE("drain_full with V: dump sweep after counter reads, clobbers undone, "
          "and NO resume request issued")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaV;
  bus.regfile[hybrid::regno_csr(0xC22)] = 32;
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x600ULL;  // VS on
  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
  bus.regfile[hybrid::regno_gpr(7)] = 0x77;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.vl    == 16u);
  CHECK(state.vtype == 0xC1ULL);

  // Sweep present and after the minstret read.
  const auto last_vse =
    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
  REQUIRE(last_vse.has_value());

  // Clobbers undone: undo vsetvl after the sweep, x5/x6/x7 rewritten last.
  const auto undo_vsetvl =
    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
  REQUIRE(undo_vsetvl.has_value());
  CHECK(*last_vse < *undo_vsetvl);
  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
  REQUIRE(!x5_writes.empty());
  REQUIRE(!x7_writes.empty());
  CHECK(x5_writes.back().second == 0x55u);
  CHECK(x7_writes.back().second == 0x77u);

  // drain_full never resumes -- the caller (step loop / exit) decides.
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kDmcontrol)
      CHECK((op.value & RD::kDmcontrolResumereq) == 0u);
  }
}

TEST_CASE("drain_full with FS off in mstatus: forces FS on for the FPR reads, "
          "then restores the original mstatus; the record keeps the original")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaF | kMisaD;
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x1800ULL;  // FS = Off

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.mstatus == 0x1800ULL);

  const auto ms_writes =
    abstract_writes_to(bus.ops, hybrid::regno_csr(RD::kCsrMstatus));
  REQUIRE(ms_writes.size() >= 2);
  // First write enables FS (Initial), final write restores the original.
  CHECK((ms_writes.front().second & RD::kMstatusFsMask) != 0u);
  CHECK(ms_writes.back().second == 0x1800ULL);

  // The enable precedes the first FPR read.
  std::optional<std::size_t> first_fpr;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const uint16_t regno = op.value & 0xFFFFu;
    if (regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31)) {
      first_fpr = i;
      break;
    }
  }
  REQUIRE(first_fpr.has_value());
  CHECK(ms_writes.front().first < *first_fpr);
}

TEST_CASE("L6: drain reads the hart privilege from dcsr.prv")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // dcsr: xdebugver=4, cause=3 (haltreq), prv=1 (S-mode at halt).
  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x400000C1ULL;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  CHECK(state.priv == 1u);
}

TEST_CASE("L6: drain_with_passthrough reports the freshly drained privilege, "
          "not the QEMU1 snapshot's")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x40000000ULL;  // prv=0 (U)

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;  // stale: QEMU1 drained M before the ROI dropped to U

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.priv == 0u);
}

// Oracle differential compare (verify_oracle F2): field-wise diff of two
// drained hybrid_state_v1 records -- the QEMU oracle's exit-boundary drain
// (ref) against the hybrid run's vsim drain (got).
//
// Compare policy, fixed by what vsim's drain freshly reads (state_drain.hpp
// drain_with_passthrough):
//   strict:  magic/version/flags/hart_id/priv (identity), pc, gpr[0..31];
//            fpr[0..31] under FLAG_FP; vstart/vtype/vl/vlenb/vxsat/vxrm/vcsr
//            and the vreg bytes under FLAG_V.
//   skipped: mstatus, mepc, mtvec, mcause, mtval, mscratch, medeleg,
//            mideleg, mip, mie, satp, pmpcfg[], pmpaddr[] -- passthrough on
//            the vsim side (copied from QEMU1's ENTRY snapshot, never
//            re-read), so comparing them would test entry-vs-exit.
//   masked:  mcycle, minstret, mcycle/minstret_at_measure_start -- the
//            engines count cycles/insns differently by design.
#ifndef ANDES_SIM_STATE_DIFF_HPP
#define ANDES_SIM_STATE_DIFF_HPP

#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// One strictly-compared field that differs: "pc", "x5", "f31", "vl",
// "v3[7]" (register + byte offset), "flags", ...
struct FieldDiff {
  std::string field;
  unsigned long long ref = 0;
  unsigned long long got = 0;
};

struct DiffReport {
  int compared = 0;  // count of strictly compared fields
  std::vector<FieldDiff> diffs;
  bool ok() const { return diffs.empty(); }
};

// compare_trap_cause (cosim_redesign F6, lock-step): also compare mepc and
// mcause -- the well-defined trap fields that reveal a mishandled trap. Still
// EXCLUDES mtval (implementation-defined for illegal insns) and mstatus
// (dirty-bit differences), which would false-positive across QEMU vs RTL.
// Default false preserves the hybrid-ROI policy above (trap CSRs passthrough).
DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
                       bool compare_trap_cause = false);

// Print `r` as "[state-diff] ..." lines: one per mismatch, then the
// PASS/FAIL verdict. Shared by the state-diff subcommand and run --verify.
void print_diff_report(const DiffReport& r);

}  // namespace andes_sim

#endif  // ANDES_SIM_STATE_DIFF_HPP

